import { useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import {
  getDashboardStats,
  getKycRequests,
  getNotifications
} from '../api/dashboardApi';

/* ---------------- Sparkline ---------------- */

const sparkConfigs = {
  'Total Users':   { color:'#3B82F6', points:[30,35,32,40,38,45,42,50,48,55,52,60] },
  'Pending KYC':   { color:'#F59E0B', points:[20,25,28,22,30,35,32,38,36,42,40,45] },
  'Approved KYC':  { color:'#10B981', points:[40,38,45,50,48,55,52,58,56,62,60,68] },
  'Rejected KYC':  { color:'#EF4444', points:[30,28,26,24,22,20,22,18,16,14,12,10] },
};

function Sparkline({ label }) {
  const cfg = sparkConfigs[label] || { color:'#3B82F6', points:[30,35,40,38,45,42,50] };
  const { color, points } = cfg;

  const w = 80, h = 32, pad = 2;
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;

  const xs = points.map((_, i) => pad + (i / (points.length - 1)) * (w - pad * 2));
  const ys = points.map(v => h - pad - ((v - min) / range) * (h - pad * 2));

  const polyline = xs.map((x, i) => `${x},${ys[i]}`).join(' ');

  const fillPath =
    `M${xs[0]},${ys[0]} ` +
    xs.slice(1).map((x, i) => `L${x},${ys[i+1]}`).join(' ') +
    ` L${xs[xs.length-1]},${h} L${xs[0]},${h} Z`;

  return (
    <svg width={w} height={h}>
      <defs>
        <linearGradient id={`sg-${label.replace(/\s/g,'')}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.25" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>

      <path d={fillPath} fill={`url(#sg-${label.replace(/\s/g,'')})`} />

      <polyline
        points={polyline}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

/* ---------------- Donut Chart ---------------- */

function DonutChart({ stats }) {

  const approved = Number(stats.find(s => s.label === 'Approved KYC')?.value || 0);
  const pending  = Number(stats.find(s => s.label === 'Pending KYC')?.value || 0);
  const rejected = Number(stats.find(s => s.label === 'Rejected KYC')?.value || 0);

  const total = approved + pending + rejected;

  const successRate = total ? ((approved / total) * 100).toFixed(1) : 0;

  const r = 68;
  const cx = 88;
  const cy = 88;
  const sw = 18;
  const c = 2 * Math.PI * r;

  const aPct = total ? approved / total : 0;
  const pPct = total ? pending / total : 0;

  return (
    <div>
      <svg width="176" height="176">

        <circle cx={cx} cy={cy} r={r} fill="none" stroke="#FEE2E2" strokeWidth={sw} />

        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke="#FEF3C7"
          strokeWidth={sw}
          strokeDasharray={`${(aPct + pPct) * c} ${c}`}
          strokeDashoffset={-aPct * c}
          transform={`rotate(-90 ${cx} ${cy})`}
        />

        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke="#10B981"
          strokeWidth={sw}
          strokeDasharray={`${aPct * c} ${c}`}
          transform={`rotate(-90 ${cx} ${cy})`}
        />

      </svg>

      <div style={{ textAlign:'center' }}>
        <h2>{successRate}%</h2>
        <p>Success Rate</p>
      </div>
    </div>
  );
}

/* ---------------- Status Badge ---------------- */

const statusBadge = (s) => {
  const m = {
    Pending:'b-pending',
    'In Review':'b-review',
    Approved:'b-approved',
    Failed:'b-failed'
  };

  return <span className={`badge ${m[s] || 'b-pending'}`}>{s || 'Pending'}</span>;
};

/* ---------------- Activity Icon ---------------- */

const actIcon = (t) => {
  if (t === 'kyc_approved') return { bg:'#F0FDF4', e:'✅' };
  if (t === 'kyc_rejected') return { bg:'#FEF2F2', e:'❌' };
  if (t === 'system') return { bg:'#FFFBEB', e:'⚠️' };
  return { bg:'#EFF6FF', e:'🔔' };
};

/* ---------------- MAIN DASHBOARD ---------------- */

export default function Dashboard() {

  const navigate = useNavigate();

  const defaultStats = [
    { label:'Total Users', value:'0', change:'0%', up:true, bg:'#EFF6FF', emoji:'👥' },
    { label:'Pending KYC', value:'0', change:'0%', up:true, bg:'#FFFBEB', emoji:'⏳' },
    { label:'Approved KYC', value:'0', change:'0%', up:true, bg:'#F0FDF4', emoji:'✅' },
    { label:'Rejected KYC', value:'0', change:'0%', up:false, bg:'#FEF2F2', emoji:'❌' },
  ];

  const [stats, setStats] = useState(defaultStats);
  const [kycRequests, setKycRequests] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const statsRes = await getDashboardStats();
      const kycRes = await getKycRequests();
      const notificationsRes = await getNotifications();

      setStats(statsRes?.length ? statsRes : defaultStats);
      setKycRequests(kycRes || []);
      setNotifications(notificationsRes || []);
    } catch (err) {
      console.log("Dashboard API Error:", err);
    }
  };

  return (
    <div>

      <h2>Dashboard</h2>

      <div>
        {stats.map((s, i) => (
          <div key={i}>
            <h4>{s.label}</h4>
            <p>{s.value}</p>
            <Sparkline label={s.label} />
          </div>
        ))}
      </div>

      <div>
        <h3>Recent KYC</h3>
        {kycRequests.slice(0,5).map((r,i) => (
          <div key={i}>
            {r.name} - {statusBadge(r.status)}
          </div>
        ))}
      </div>

      <div>
        <h3>Notifications</h3>
        {notifications.slice(0,4).map((n,i) => {
          const ic = actIcon(n.type);
          return (
            <div key={i}>
              <span style={{background:ic.bg}}>{ic.e}</span>
              {n.title}
            </div>
          );
        })}
      </div>

    </div>
  );
}
